// agentpager-opencode v22
// AgentPager (OpenCode) bridge plugin
// Managed by AgentPager (OpenCode) - do not edit this file manually.
// Forwards opencode events to the local AgentPager Bridge on 127.0.0.1:49361.
//
// v22 与 v21 的区别：正文节流器增加 Trailing-Edge 定时器（300ms 延迟 Flush），杜绝流式突发中断或停顿导致的尾帧丢字。

import net from "node:net"

const HOST = "127.0.0.1"
const PORT = 49361
const CONNECT_TIMEOUT_MS = 500
const MAX_TEXT = 1000
const MAX_VALUE = 300
const REPLY_PREVIEW_LIMIT = 120
const REPLY_THROTTLE_MS = 300
const REPLY_ACCUM_LIMIT = 256_000
const MESSAGE_IDS_LIMIT = 4000
// 远程审批/作答最多挂多久等手机；超时就放弃（审批交回本地询问、作答不干预），绝不把 opencode 卡死
const HOLD_TIMEOUT_MS = 600_000

const INPUT_KEYS = [
  "command",
  "description",
  "filePath",
  "file_path",
  "path",
  "pattern",
  "query",
  "url",
  "subagent_type",
  "agent",
  "skill",
]

function cap(value, limit) {
  if (typeof value !== "string") return undefined
  const text = value.replace(/\s+/g, " ").trim()
  if (text.length === 0) return undefined
  return text.length > limit ? text.slice(0, limit) : text
}

function pickInput(input) {
  if (!input || typeof input !== "object") return undefined
  const result = {}
  for (const key of INPUT_KEYS) {
    const value = cap(input[key], MAX_VALUE)
    if (value !== undefined) result[key] = value
  }
  return Object.keys(result).length > 0 ? result : undefined
}

function trimError(error) {
  if (!error || typeof error !== "object") return undefined
  const data = error.data && typeof error.data === "object" ? error.data : {}
  return {
    name: typeof error.name === "string" ? error.name : "Error",
    message: cap(data.message ?? error.message, MAX_VALUE),
  }
}

function trimSession(info) {
  if (!info || typeof info !== "object") return undefined
  return {
    id: info.id,
    parentID: info.parentID,
    directory: info.directory,
    title: cap(info.title, 200),
    time: info.time ? { created: info.time.created, updated: info.time.updated } : undefined,
  }
}

// opencode 的插件工厂签名是 (input: PluginInput, options?) —— input 里带 client / directory，
// 远程审批要用它们替 opencode 答复权限（见 replyPermission）。
export const AgentPagerOpenCode = async (input) => {
  const childSessions = new Set()
  const ownSessions = new Set()
  const toolSignatures = new Map()
  const assistantMessages = new Set()
  const summaryMessages = new Set()
  const partTypes = new Map()
  const replies = new Map()
  const runningSessions = new Set()
  const queuedSessions = new Set()
  const childParent = new Map()
  // 乱序残帧守卫：某会话最近一次工具事件的**开始时刻**（ms）。
  // v8 用"有没有收到过工具事件"这种到达顺序判定，会把**合法的**结束帧一起丢掉（见下方注释）；
  // v11 改成比时间戳：正文的 time.end 早于工具 time.start 才算残帧。
  const toolStartedAt = new Map()
  let queue = Promise.resolve()

  function send(payload) {
    return new Promise((resolve) => {
      const socket = net.connect({ host: HOST, port: PORT })
      let settled = false
      const finish = () => {
        if (settled) return
        settled = true
        socket.destroy()
        resolve()
      }
      socket.setTimeout(CONNECT_TIMEOUT_MS)
      socket.on("connect", () => {
        socket.write(JSON.stringify({ hook_source: "opencode", payload }) + "\n")
      })
      socket.on("data", finish)
      socket.on("end", finish)
      socket.on("error", finish)
      socket.on("timeout", finish)
    })
  }

  // 权限询问的远程审批：挂给桥等手机，拿到答复后**用 opencode 自己的接口回复**。
  //
  // 为什么不用插件的 permission.ask 钩子：那个钩子类型虽然早就在 SDK 里（2026-08-24 起），
  // 但**装好的 1.18.35 根本不触发它**（实测：注册了、真机零触发，桥日志一条挂起记录都没有 ✗；
  // 安装版二进制里也没有 trigger("permission.ask") ✗）。而下面这条"替 opencode 回复"的路
  // 在 1.18.35 上就现成 —— opencode 自己的 TUI 在 auto 模式下就是这么答复权限的。
  //
  // 客户端形状按**运行时可用的那个**挑：不同版本给的 client 封装不同 ——
  // 新版是 permission.reply({requestID, reply})，SDK 生成的那版是
  // postSessionIdPermissionsPermissionId({path:{id, permissionID}, body:{response}})。
  // 两个都没有时打一条 WARN 把可用键列出来，方便下一轮定位（不猜）。
  async function replyPermission(sessionID, requestID, allow) {
    const client = input?.client
    const response = allow ? "once" : "reject"   // 标准：允许 = allow once（一次性），拒绝 = reject
    if (!client || typeof sessionID !== "string" || typeof requestID !== "string" || requestID.length === 0) return
    try {
      if (typeof client.permission?.reply === "function") {
        await client.permission.reply({ requestID, reply: response, directory: input?.directory })
        return
      }
      if (typeof client.postSessionIdPermissionsPermissionId === "function") {
        await client.postSessionIdPermissionsPermissionId({
          // **两个键都给**：这条路由的 path 参数名各家版本不同 —— 装好的 1.18.35 是 {sessionID}，
          // 而更新的那版是 {id}（实测：传错键时模板不会被替换，URL 直接坏掉 → 404 → 手机上"点了没反应" ✗）。
          // 生成器只会读它声明过的那个键，多余的键被忽略 ✓，所以两个都带上最稳。
          path: { sessionID, id: sessionID, permissionID: requestID },
          body: { response },
          query: input?.directory ? { directory: input.directory } : undefined,
        })
        return
      }
      const keys = client && typeof client === "object"
        ? Object.keys(client).filter((key) => /permission|session|question/i.test(key)).slice(0, 12)
        : []
      reportNote("没有可用的权限回复接口，client 上相关键：" + JSON.stringify(keys))
    } catch (error) {
      reportNote("权限回复失败：" + (error && error.message ? error.message : String(error)))
    }
  }

  // 作答：把手机上选好的答案交给 opencode。
  //
  // 答复形状是"**每题一组已选 label 数组**，按题序"——内层多选、外层多题，同一个形状
  // （安装版 1.18.35 的 schema 原文："User answers in order of questions (each answer is
  // an array of selected labels)"），所以桥那边攒齐了什么都不用再拼，原样转发即可。
  //
  // 回复接口与审批一样是**按版本生成的**，同一个方法在相邻版本里名字/参数就能变 ✗
  // （审批踩过：path 键 `{sessionID}` ↔ `{id}`，传错就直接 404 且手机上毫无痕迹）。
  // 所以按"运行时可用的那个"逐层降级，一层都不成就把可用键报回桥——不猜。
  async function replyQuestion(sessionID, requestID, answers) {
    if (typeof requestID !== "string" || requestID.length === 0 || !Array.isArray(answers)) return
    const client = input?.client
    const directory = input?.directory
    const body = { answers }
    try {
      // ① 新版封装：client.question.reply({requestID, directory, answers})
      if (typeof client?.question?.reply === "function") {
        await client.question.reply({ requestID, directory, answers })
        return
      }
      // ② 再新一版的生成式分组
      if (typeof client?.session?.question?.reply === "function") {
        await client.session.question.reply({ sessionID, requestID, answers })
        return
      }
      // ③ **装好的 1.18.35 走这条**：它的插件 client（内部类是 R7）上压根没有 question 分组，
      //    但每个方法体都是 `this._client.post({url, path, body, headers})` —— 照抄它的调用约定，
      //    并且用的是**它自己那个 fetch**（TUI 无独立端口时是进程内直连，外面 fetch 打不进来）。
      if (typeof client?._client?.post === "function") {
        await client._client.post({
          url: "/question/{requestID}/reply",
          path: { requestID },
          body,
          headers: { "Content-Type": "application/json" },
        })
        return
      }
      // ④ 兜底：直接打服务端（路由 `POST /question/{requestID}/reply`，两侧同一份 schema）
      const base = input?.serverUrl
      if (base) {
        const response = await fetch(new URL(`/question/${encodeURIComponent(requestID)}/reply`, base), {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            ...(directory ? { "x-opencode-directory": encodeURIComponent(directory) } : {}),
          },
          body: JSON.stringify(body),
        })
        if (!response.ok) reportNote("作答接口返回 " + response.status)
        return
      }
      const keys = client && typeof client === "object"
        ? Object.keys(client).filter((key) => /question|session|permission|client/i.test(key)).slice(0, 12)
        : []
      reportNote("没有可用的作答接口，client 上相关键：" + JSON.stringify(keys))
    } catch (error) {
      reportNote("作答失败：" + (error && error.message ? error.message : String(error)))
    }
  }

  // 插件侧事件与异常报回桥（落盘在桥日志中，不污染 OpenCode 终端界面）：
  function reportNote(note) {
    try {
      enqueue({ event: "plugin.note", properties: { note: String(note).slice(0, 300) } })
    } catch { /* 忽略 */ }
  }

  // 远程 Prompt：通过 Bridge 的控制通道接收手机端指令，调用 OpenCode 的 promptAsync 执行
  async function executeRemotePrompt(sessionID, text) {
    if (typeof text !== "string" || text.trim().length === 0) return
    const client = input?.client
    const directory = input?.directory
    const body = { parts: [{ type: "text", text: text.trim() }] }
    try {
      if (typeof client?.promptAsync === "function") {
        await client.promptAsync({
          path: { sessionID, id: sessionID },
          query: directory ? { directory } : undefined,
          body,
        })
        reportNote(`远程 prompt 已通过 promptAsync 注入（会话 ${sessionID}）`)
        return
      }
      if (typeof client?._client?.post === "function") {
        await client._client.post({
          url: "/session/{id}/prompt_async",
          path: { sessionID, id: sessionID },
          query: directory ? { directory } : undefined,
          body,
          headers: { "Content-Type": "application/json" },
        })
        reportNote(`远程 prompt 已通过 _client.post 注入（会话 ${sessionID}）`)
        return
      }
      const base = input?.serverUrl
      if (base && sessionID) {
        const response = await fetch(new URL(`/session/${encodeURIComponent(sessionID)}/prompt_async`, base), {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            ...(directory ? { "x-opencode-directory": encodeURIComponent(directory) } : {}),
          },
          body: JSON.stringify(body),
        })
        if (!response.ok) reportNote("远程 prompt 接口返回 " + response.status)
        return
      }
      reportNote("没有可用的 promptAsync / post 接口")
    } catch (error) {
      reportNote("远程 prompt 注入失败：" + (error && error.message ? error.message : String(error)))
    }
  }

  // 维持一条连向 Bridge 的常驻控制监听连接（用于双向接收指令）
  let controlSocket = null
  let controlReconnectTimer = null
  let isDisposed = false

  function startControlChannel() {
    if (isDisposed) return
    try {
      controlSocket = net.connect({ host: HOST, port: PORT })
    } catch {
      scheduleControlReconnect()
      return
    }

    controlSocket.on("connect", () => {
      controlSocket.setTimeout(0)
      try {
        controlSocket.write(JSON.stringify({ hook_source: "opencode", payload: { event: "control.attach" } }) + "\n")
      } catch {
        controlSocket.destroy()
      }
    })

    let buffer = ""
    controlSocket.on("data", async (chunk) => {
      buffer += chunk.toString("utf8")
      let index
      while ((index = buffer.indexOf("\n")) >= 0) {
        const line = buffer.slice(0, index).trim()
        buffer = buffer.slice(index + 1)
        if (line) {
          try {
            const cmd = JSON.parse(line)
            if (cmd.action === "prompt" && typeof cmd.text === "string") {
              await executeRemotePrompt(cmd.sessionID, cmd.text)
            }
          } catch (err) {
            reportNote("解析控制指令异常：" + (err && err.message ? err.message : String(err)))
          }
        }
      }
    })

    controlSocket.on("error", () => {
      controlSocket?.destroy()
    })

    controlSocket.on("close", () => {
      controlSocket = null
      scheduleControlReconnect()
    })
  }

  function scheduleControlReconnect() {
    if (isDisposed || controlReconnectTimer) return
    controlReconnectTimer = setTimeout(() => {
      controlReconnectTimer = null
      startControlChannel()
    }, 3000)
    if (controlReconnectTimer.unref) controlReconnectTimer.unref()
  }

  startControlChannel()

  async function holdApproval(sessionID, properties) {
    if (typeof sessionID !== "string") return
    const reply = await request({ event: "permission.asked", hold: "approval", properties }, HOLD_TIMEOUT_MS)
    if (!reply) return   // 桥不在 / 超时 / 手机没答：什么都不做，本地询问照常
    if (reply.decision !== "allow" && reply.decision !== "deny") return
    await replyPermission(sessionID, properties.id, reply.decision === "allow")
  }

  // 提问的远程作答：与审批同一条节奏——挂一条连接给桥等手机，拿到答案再用 opencode 自己的接口答复。
  // 返回 undefined（桥不在 / 超时 / 手机没答 / 用户在终端自己答了）时就什么都不做，本地对话框照常。
  async function holdQuestion(sessionID, properties) {
    if (typeof sessionID !== "string") return
    const reply = await request(
      { event: "question.asked", hold: "question", request_id: properties.id, properties },
      HOLD_TIMEOUT_MS,
    )
    if (!reply) return
    await replyQuestion(sessionID, properties.id, reply.answers)
  }

  // 请求-应答：与 send 的"即发即走"不同——这里**保持连接不关**，等桥回一行 JSON。
  // 用途：权限询问与提问都要攥住这次询问，等手机在 App 上答复（审批 / 作答都走它）。
  // 连上之后必须把连接超时清零：挂住期间对面本来就长时间不说话，500ms 的空闲超时会把它掐掉。
  function request(payload, timeoutMs) {
    return new Promise((resolve) => {
      let settled = false
      let socket
      const finish = (value) => {
        if (settled) return
        settled = true
        try { socket?.destroy() } catch { /* 忽略 */ }
        resolve(value)
      }
      try {
        socket = net.connect({ host: HOST, port: PORT })
      } catch {
        resolve(null)
        return
      }
      const timer = setTimeout(() => finish(null), timeoutMs)
      if (timer.unref) timer.unref()
      socket.setTimeout(CONNECT_TIMEOUT_MS)
      socket.on("connect", () => {
        socket.setTimeout(0)
        try {
          socket.write(JSON.stringify({ hook_source: "opencode", payload }) + "\n")
        } catch {
          finish(null)
        }
      })
      let buffer = ""
      socket.on("data", (chunk) => {
        buffer += chunk.toString()
        const index = buffer.indexOf("\n")
        if (index < 0) return
        clearTimeout(timer)
        let parsed = null
        try { parsed = JSON.parse(buffer.slice(0, index)) } catch { parsed = null }
        finish(parsed)
      })
      socket.on("end", () => finish(null))
      socket.on("error", () => finish(null))
      socket.on("timeout", () => finish(null))
    })
  }

  function rememberToolSignature(id, signature) {
    toolSignatures.set(id, signature)
    if (toolSignatures.size > MESSAGE_IDS_LIMIT) toolSignatures.clear()
  }

  function enqueue(payload) {
    queue = queue.then(() => send(payload)).catch(() => {})
    return queue
  }

  function noteSession(info) {
    if (!info || typeof info.id !== "string") return
    if (info.parentID) {
      childSessions.add(info.id)
      if (typeof info.parentID === "string") childParent.set(info.id, info.parentID)
    } else ownSessions.add(info.id)
  }

  function parseAgent(title) {
    if (typeof title !== "string") return undefined
    const match = title.match(/\(@([A-Za-z0-9_-]+) subagent\)\s*$/)
    return match ? match[1] : undefined
  }

  function childToolStep(part, state) {
    if (state.status === "error") {
      const error = cap(state.error, MAX_VALUE)
      if (error) return cap("✗ " + error, MAX_VALUE)
    }
    const title = cap(state.title, MAX_VALUE)
    if (title) return title
    const input = pickInput(state.input)
    const summary = input ? Object.values(input)[0] : undefined
    return cap([part.tool, summary].filter(Boolean).join(" "), MAX_VALUE)
  }

  function sendSubagent(childID, phase, extra) {
    const parentID = childParent.get(childID)
    if (typeof parentID !== "string") return
    enqueue({ event: "subagent", properties: { sessionID: parentID, id: childID, phase, ...extra } })
  }

  function sessionIDOf(properties) {
    if (!properties || typeof properties !== "object") return undefined
    if (typeof properties.sessionID === "string") return properties.sessionID
    if (properties.info && typeof properties.info.id === "string") return properties.info.id
    return undefined
  }

  function isChild(properties) {
    const sessionID = sessionIDOf(properties)
    return sessionID !== undefined && childSessions.has(sessionID)
  }

  async function handle(event) {
    const properties = event?.properties ?? {}
    switch (event?.type) {
      case "session.created":
      case "session.updated":
      case "session.deleted": {
        noteSession(properties.info)
        if (event.type === "session.deleted") {
          const deletedID = sessionIDOf(properties)
          if (typeof deletedID === "string") {
            // 子会话被删除（中止/清掉）必须**先补一条终态再断映射**：旧实现只删映射不发信号，
            // 桥侧那条子代理行会永远停在 running，直到父任务终结才被 SubagentSweep 扫掉。
            // 正常跑完的子会话早由 session.idle 发过 done，桥对已终态的行会忽略后续相位，
            // 所以补 failed 不会把"完成"误报成"中断"。
            // 位置很关键：必须在这几行 delete 之前——sendSubagent 要靠 childParent 找父会话，
            // 而本块末尾的 isChild() 也已经为假（childSessions 刚被删掉），插在那边等于发不出去。
            if (childSessions.has(deletedID)) sendSubagent(deletedID, "failed", { step: "子代理会话已中止" })
            runningSessions.delete(deletedID)
            queuedSessions.delete(deletedID)
            childSessions.delete(deletedID)
            childParent.delete(deletedID)
            if (replies.has(deletedID)) {
              const r = replies.get(deletedID)
              if (r && r.timer) clearTimeout(r.timer)
              replies.delete(deletedID)
            }
            toolStartedAt.delete(deletedID)
          }
        }
        if (isChild(properties)) {
          const childID = sessionIDOf(properties)
          if (typeof childID === "string" && event.type === "session.created") {
            sendSubagent(childID, "started", {
              agent: parseAgent(properties.info?.title),
              title: cap(properties.info?.title, 200),
            })
          }
          return
        }
        enqueue({ event: event.type, properties: { sessionID: sessionIDOf(properties), info: trimSession(properties.info) } })
        return
      }
      case "session.status": {
        const sessionID = sessionIDOf(properties)
        const status = properties.status ?? {}
        if (typeof sessionID === "string") {
          if (status.type === "busy") runningSessions.add(sessionID)
          else if (status.type === "idle") runningSessions.delete(sessionID)
        }
        if (isChild(properties)) {
          if (status.type === "idle" && typeof sessionID === "string") sendSubagent(sessionID, "done", {})
          return
        }
        enqueue({
          event: "session.status",
          properties: {
            sessionID,
            status: { type: status.type, attempt: status.attempt, message: cap(status.message, MAX_VALUE) },
          },
        })
        return
      }
      case "session.idle": {
        const sessionID = sessionIDOf(properties)
        if (typeof sessionID === "string") runningSessions.delete(sessionID)
        if (isChild(properties)) {
          if (typeof sessionID === "string") sendSubagent(sessionID, "done", {})
          return
        }
        enqueue({ event: "session.idle", properties: { sessionID } })
        return
      }
      case "session.error": {
        const sessionID = sessionIDOf(properties)
        if (isChild(properties)) {
          if (typeof sessionID === "string") {
            const error = properties.error ?? {}
            sendSubagent(sessionID, "failed", { step: cap(error?.data?.message ?? error?.message, MAX_VALUE) })
          }
          return
        }
        enqueue({ event: "session.error", properties: { sessionID, error: trimError(properties.error) } })
        return
      }
      case "message.updated": {
        const info = properties.info
        if (!info || info.role !== "assistant") return
        if (typeof info.sessionID === "string" && childSessions.has(info.sessionID)) {
          const completed = info.time && typeof info.time.completed === "number"
          if (completed && info.tokens) sendSubagent(info.sessionID, "tokens", { tokens: info.tokens })
          return
        }
        if (typeof info.id === "string") {
          if (info.summary === true) summaryMessages.add(info.id)
          else assistantMessages.add(info.id)
          if (assistantMessages.size > MESSAGE_IDS_LIMIT) assistantMessages.clear()
          if (summaryMessages.size > MESSAGE_IDS_LIMIT) summaryMessages.clear()
        }
        const completed = info.time && typeof info.time.completed === "number"
        // 新的 assistant 消息开始生成 = 之前排队的 prompt 被接单 → 清除排队标记
        if (!completed && !info.error && typeof info.sessionID === "string" && queuedSessions.has(info.sessionID)) {
          queuedSessions.delete(info.sessionID)
          enqueue({ event: "prompt.active", properties: { sessionID: info.sessionID } })
        }
        if (!completed && !info.error) return
        enqueue({
          event: "message.updated",
          properties: {
            sessionID: info.sessionID,
            info: {
              role: "assistant",
              time: info.time,
              error: trimError(info.error),
              tokens: info.tokens,
              modelID: info.modelID,
              providerID: info.providerID,
            },
          },
        })
        return
      }
      case "message.part.delta": {
        // 正文流（assistant 的 text part）：累积并节流转发预览；reasoning 等其它 part 不转发。
        const { sessionID, messageID, partID, field, delta } = properties
        if (field !== "text" || typeof delta !== "string" || delta.length === 0) return
        if (typeof sessionID !== "string" || childSessions.has(sessionID)) return
        if (typeof messageID !== "string" || !assistantMessages.has(messageID) || summaryMessages.has(messageID)) return
        if (partTypes.get(partID) !== "text") return
        // 这里 v8 会清掉"有工具事件"的标记；v11 改用时间戳判定（见结束帧分支），不再需要。
        const previous = replies.get(sessionID)
        if (previous && previous.partID !== partID && previous.timer) {
          clearTimeout(previous.timer)
          previous.timer = null
        }
        const entry = previous && previous.partID === partID
          ? { ...previous, text: (previous.text + delta).slice(0, REPLY_ACCUM_LIMIT) }
          : { partID, text: delta.slice(0, REPLY_ACCUM_LIMIT), sentAt: 0, sentText: undefined, sentLength: 0, timer: null }
        const preview = cap(entry.text, REPLY_PREVIEW_LIMIT)
        const now = Date.now()
        const textGrown = entry.text.length > (entry.sentLength || 0)
        if (preview && (preview !== entry.sentText || textGrown)) {
          if (now - entry.sentAt >= REPLY_THROTTLE_MS) {
            if (entry.timer) {
              clearTimeout(entry.timer)
              entry.timer = null
            }
            entry.sentAt = now
            entry.sentText = preview
            entry.sentLength = entry.text.length
            enqueue({ event: "reply", properties: { sessionID, text: preview, fullText: entry.text } })
          } else if (!entry.timer) {
            // Trailing Edge 定时器（v22 修）：防止流式在 300ms 窗口内突发结束导致尾部丢失
            const delay = Math.max(0, REPLY_THROTTLE_MS - (now - entry.sentAt))
            entry.timer = setTimeout(() => {
              const cur = replies.get(sessionID)
              if (!cur || cur.partID !== partID) return
              cur.timer = null
              const curPreview = cap(cur.text, REPLY_PREVIEW_LIMIT)
              const curGrown = cur.text.length > (cur.sentLength || 0)
              if (curPreview && (curPreview !== cur.sentText || curGrown)) {
                cur.sentAt = Date.now()
                cur.sentText = curPreview
                cur.sentLength = cur.text.length
                enqueue({ event: "reply", properties: { sessionID, text: curPreview, fullText: cur.text } })
              }
            }, delay)
          }
        }
        replies.set(sessionID, entry)
        return
      }
      case "message.part.updated": {
        const part = properties.part
        if (!part) return
        if (typeof part.sessionID === "string" && childSessions.has(part.sessionID)) {
          if (part.type === "tool") {
            const state = part.state ?? {}
            const signature = [state.status, state.title ?? "", state.error ?? ""].join("\u0000")
            if (toolSignatures.get(part.id) !== signature) {
              rememberToolSignature(part.id, signature)
              sendSubagent(part.sessionID, "tool", {
                tool: part.tool,
                step: childToolStep(part, state),
                title: cap(state.title, MAX_VALUE),
                error: cap(state.error, MAX_VALUE),
                // 命令文本必须带给桥：桥靠它判"这是不是测试命令"（蓝/橙之分）。
                // 子代理事件原先不带它，桥只能传 null，于是同一个 `npm test`
                // 父任务行是蓝（测试）、它自己的子代理行却是橙（执行）。
                command: cap(state.input?.command, MAX_VALUE),
              })
            }
          }
          return
        }
        if (typeof part.id === "string" && typeof part.type === "string") {
          partTypes.set(part.id, part.type)
          if (partTypes.size > MESSAGE_IDS_LIMIT) partTypes.clear()
        }
        if (part.type === "text") {
          // 正文 part 结束：用权威全文补一次最终预览（此前可能因节流缺失末尾）。
          //
          // **残帧判定必须比时间戳，不能比到达顺序**（v11 修）：工具 part 与结束帧可以反序到达
          // ~200ms（v8 就是为此加的守卫），但"反序到达"不等于"内容是旧的"——正文写完**接着**调工具
          // 是常规时序，它的结束帧同样晚到、内容是**新的**。v8 一律丢弃的后果：用户手机上那行
          // 只剩流式期节流发出的开头两三个字（"什么数据库"），后面整段话再也不更新 ✗。
          // 现在按 opencode 自己的时间戳判：schema（packages/schema/src/v1/session.ts）
          // TextPart.time = { start, end }、ToolState*.time.start 都是毫秒时间戳，
          // **结束帧的 time.end 早于最近一次工具 time.start 才是残帧**，其余照收。
          const toolAt = toolStartedAt.get(part.sessionID)
          const stale = typeof toolAt === "number" && typeof part.time?.end === "number" && part.time.end <= toolAt
          if (assistantMessages.has(part.messageID) && !summaryMessages.has(part.messageID) &&
              part.time && typeof part.time.end === "number" && !stale) {
            const preview = cap(part.text, REPLY_PREVIEW_LIMIT)
            const previous = replies.get(part.sessionID)
            if (previous && previous.timer) {
              clearTimeout(previous.timer)
              previous.timer = null
            }
            const fullText = typeof part.text === "string" ? part.text.slice(0, REPLY_ACCUM_LIMIT) : previous?.text
            const fullLength = (fullText ?? "").length
            const alreadySent = previous &&
              previous.partID === part.id &&
              (previous.sentLength || 0) >= fullLength &&
              previous.sentText === preview
            if (preview && !alreadySent) {
              replies.set(part.sessionID, {
                partID: part.id,
                text: fullText ?? "",
                sentAt: Date.now(),
                sentText: preview,
                sentLength: fullLength,
                timer: null,
              })
              enqueue({ event: "reply", properties: { sessionID: part.sessionID, text: preview, fullText } })
            }
          }
          return
        }
        if (part.type !== "tool") return
        const state = part.state ?? {}
        const signature = [state.status, state.title ?? "", state.error ?? ""].join("\u0000")
        if (toolSignatures.get(part.id) === signature) return
        rememberToolSignature(part.id, signature)
        // 记下这次工具事件的**开始时刻**（没有就用到达时刻兜底），供结束帧判残。
        toolStartedAt.set(part.sessionID, typeof state.time?.start === "number" ? state.time.start : Date.now())
        enqueue({
          event: "message.part.updated",
          properties: {
            sessionID: part.sessionID,
            part: {
              id: part.id,
              callID: part.callID,
              tool: part.tool,
              state: {
                status: state.status,
                title: cap(state.title, MAX_VALUE),
                error: cap(state.error, MAX_VALUE),
                input: pickInput(state.input),
              },
            },
          },
        })
        return
      }
      case "permission.asked": {
        if (isChild(properties)) return
        const approvalSession = sessionIDOf(properties)
        const approvalProperties = {
          sessionID: approvalSession,
          id: properties.id,
          permission: properties.permission,
          patterns: Array.isArray(properties.patterns) ? properties.patterns.slice(0, 8) : undefined,
        }
        // **只走 hold 这一条**（2026-10-11 实测踩过）：如果这里再照旧 enqueue 一条普通事件，
        // 两帧走两条连接、谁后到谁说了算 —— 普通帧后到会把 hold 帧刚给上的能力位冲成空 ✗，
        // 手机上就只剩卡片没有按钮。hold 帧自带卡片所需的一切（sessionID/id/permission/patterns），
        // 桥侧单收它就会建卡 + 给 Approve/Deny ✓。
        //
        // 必须是**游离的**异步活：事件回调若 await 下去，就得等手机答复才返回 ✗ —— 那会把
        // opencode 的事件总线按分钟级卡住。所以 fire-and-forget，返回后照常走它自己的本地询问。
        void holdApproval(approvalSession, approvalProperties)
        return
      }
      case "permission.replied": {
        if (isChild(properties)) return
        enqueue({
          event: "permission.replied",
          properties: { sessionID: sessionIDOf(properties), requestID: properties.requestID, reply: properties.reply },
        })
        return
      }
      case "question.asked": {
        if (isChild(properties)) return
        const questionSession = sessionIDOf(properties)
        const questionProperties = {
          sessionID: questionSession,
          id: properties.id,
          questions: (Array.isArray(properties.questions) ? properties.questions.slice(0, 4) : []).map((item) => ({
            header: cap(item?.header, 120),
            question: cap(item?.question, MAX_VALUE),
            multiple: item?.multiple === true,
            // 选项带上注解（不再是裸 label）：桥端把它画成 `label（注解）`，与 Claude 那条来源同一形态。
            options: Array.isArray(item?.options)
              ? item.options
                  .slice(0, 8)
                  .map((option) => ({
                    label: cap(option?.label, 80),
                    description: cap(option?.description, MAX_VALUE),
                  }))
                  .filter((option) => option.label !== undefined)
              : [],
          })),
        }
        // 与审批同一条纪律：**只发 hold 这一帧**（2026-10-11 实测踩过）——两帧走两条连接、
        // 谁后到谁说了算，普通帧后到会把刚给上的作答能力位冲成空 ✗，手机上就只剩卡片没有按钮。
        // hold 帧自带卡片所需的全部字段（sessionID/id/questions），桥侧单收它就建卡 + 给能力位 ✓。
        //
        // 必须是**游离的**异步活：事件回调若 await 下去，就得等手机答复才返回 ✗ —— 那会把
        // opencode 的事件总线按分钟级卡住。所以 fire-and-forget，返回后照常走它自己的本地询问。
        void holdQuestion(questionSession, questionProperties)
        return
      }
      case "question.replied":
      case "question.rejected": {
        if (isChild(properties)) return
        enqueue({
          event: event.type,
          properties: { sessionID: sessionIDOf(properties), requestID: properties.requestID },
        })
        return
      }
      default:
        return
    }
  }

  return {
    event: async ({ event }) => {
      try {
        await handle(event)
      } catch {}
    },
    "chat.message": async (input, output) => {
      try {
        const sessionID = input?.sessionID
        // 子会话（task 工具派生的内部会话）一律不上报，避免幽灵任务
        if (typeof sessionID === "string" && childSessions.has(sessionID)) return
        // 排队判定：提交时该会话仍在跑（status busy / 未 idle）→ 这条 prompt 是排队状态
        const queued = typeof sessionID === "string" && runningSessions.has(sessionID)
        if (typeof sessionID === "string") {
          if (queued) queuedSessions.add(sessionID)
          else queuedSessions.delete(sessionID)
        }
        const text = (output?.parts ?? [])
          .filter((part) => part && part.type === "text" && !part.synthetic && typeof part.text === "string")
          .map((part) => part.text)
          .join("\n")
        await enqueue({
          event: "chat.message",
          properties: {
            sessionID,
            agent: cap(input?.agent, 80),
            model: input?.model ? { providerID: input.model.providerID, modelID: input.model.modelID } : undefined,
            queued,
            text: cap(text, MAX_TEXT),
          },
        })
      } catch {}
    },
    dispose: async () => {
      try {
        isDisposed = true
        if (controlReconnectTimer) clearTimeout(controlReconnectTimer)
        if (controlSocket) controlSocket.destroy()
        for (const r of replies.values()) {
          if (r && r.timer) clearTimeout(r.timer)
        }
        replies.clear()
        for (const sessionID of ownSessions) {
          await enqueue({ event: "plugin.dispose", properties: { sessionID } })
        }
        await queue
      } catch {}
    },
  }
}
